"use client";

import { useInView, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";
import type {
  CSSProperties,
  ComponentProps,
  FocusEvent,
  ReactNode,
} from "react";

import { Card } from "@/components/ui/card";
import { cn } from "@/lib/utils";

import { DEMO_PICK, FreshnessChart } from "./freshness-chart";
import type { FreshnessChartProps } from "./freshness-chart";
import { SourceChat } from "./source-chat";
import type { SourceChatProps } from "./source-chat";

/* ─────────────────────────────────────────────────────────────────────────
 * Context section. Two product windows on one tray: a chart of how fast a
 * snapshot of your knowledge goes stale, and a chat whose answer names the
 * file it read. They share one grid column, and only one is in front:
 * pointing at a window brings it forward, and the other sinks a little and
 * fades out where the two would overlap. On the keyboard the front follows
 * focus: tabbing to a window or to its title brings it forward, and since
 * the chat has nothing to tab to, it also comes forward when focus leaves
 * the chart.
 *
 * THE GRID. Twelve columns with a 0.75rem gap (--gap). The chart's window
 * spans columns 1 to 7, the chat's 7 to 12, so column 7 is shared. Each
 * window sits 1.25rem (--inset) inside its span, with its top corners
 * rounded and its bottom flush with the tray. On a phone the inset is
 * 0.75rem: the windows are stacked there, and the 16px it gives back goes
 * to the length of their lines. Nothing is measured in
 * JavaScript: every position below is a calc() over --gap, --inset and the
 * window's own width, so the fades land on the grid's lines at any width.
 *
 * THE FADE. Each window carries a mask twice its own width: solid, then a
 * fade to nothing exactly one column step (a column plus a gap) wide. Only
 * the mask's position changes. Behind, the mask is parked so the window is
 * gone where the front window begins; in front, it slides one way until the
 * fade sits just outside the window's edge. A gradient can't be transitioned
 * but its position can, which is why the mask is double width.
 *
 * ANIMATION STORYBOARD
 *
 * Read top to bottom. Each value is ms after the tray scrolls into view.
 * The chat starts in front, so the story opens there:
 *
 *    0ms   the chat answers the question it was waiting on: reading,
 *          answer, second line, sources (its own storyboard, 2.6s).
 *          Behind it the chart sweeps in (1.4s) and its number counts down
 *
 * Nothing changes places by itself: point at the chart (or tab into it)
 * and it comes forward.
 *
 * With `defaultFront="chart"` the chart opens the story and hands over:
 *
 *    0ms   the chart sweeps in (1.4s); the snapshot's number counts down
 * 1700ms   the chart points at one change by itself: the refund policy
 * 4200ms   the chat comes forward (500ms) and answers. It cites the same
 *          file.
 *
 * Touch either window before then and that story stops: from there the
 * windows only move when you ask. Stacked (below lg) the chat waits until
 * it is on screen itself. With reduced motion nothing plays; both windows
 * are complete and switch without a transition.
 * ───────────────────────────────────────────────────────────────────────── */

/** The chart-first story (`defaultFront="chart"`). */
const STORY = {
  /** The chat comes forward and starts. */
  handover: 4200,
  /** The chart points at the demo's change. */
  pick: 1700,
};

/** The stages, in order. */
const STAGE = { handover: 2, pick: 1 } as const;

type Side = "chart" | "chat";

/** How many of the twelve columns each window spans, and how many they share. */
const SPAN = { chart: 7, chat: 6, shared: 1 } as const;

/**
 * One column plus one gap, worked out from a window's own width, which is
 * its span less the inset on each side. `whole` is that width in the units
 * of where the result is used: 50% inside the mask's gradient (the mask is
 * twice the window's width), and −100% inside mask-position, where
 * percentages count backwards because the mask is wider than its box.
 */
const step = (cols: number, whole: string) =>
  `(((${whole} + 2 * var(--inset) - ${cols - 1} * var(--gap)) / ${cols}) + var(--gap))`;

/**
 * A window's mask. The window on the left fades out toward the right, and
 * the other way round. Solid for every column it doesn't share, less one:
 * that last one is the fade.
 */
const maskOf = (cols: number, side: "left" | "right") => {
  const solid = cols - SPAN.shared - 1;
  const inGradient = step(cols, "50%");
  const inPosition = step(cols, "-100%");
  return {
    back: side === "left" ? "100% 0" : "0 0",
    front:
      side === "left"
        ? `calc(-${solid} * ${inPosition}) 0`
        : `calc(100% + ${solid} * ${inPosition}) 0`,
    image: `linear-gradient(to ${side === "left" ? "right" : "left"}, #fff calc(50% + ${solid} * ${inGradient}), transparent calc(50% + ${solid + 1} * ${inGradient}))`,
  };
};

const MASK = {
  chart: maskOf(SPAN.chart, "left"),
  chat: maskOf(SPAN.chat, "right"),
};

/** A window's mask and lift for where it stands: in front, or behind. */
const standing = (side: Side, front: boolean): CSSProperties => {
  const mask = MASK[side];
  const position = front ? mask.front : mask.back;
  return {
    WebkitMaskImage: mask.image,
    WebkitMaskPosition: position,
    WebkitMaskRepeat: "no-repeat",
    WebkitMaskSize: "200% 100%",
    maskImage: mask.image,
    maskPosition: position,
    maskRepeat: "no-repeat",
    maskSize: "200% 100%",
    transform: front ? "translateY(0)" : "translateY(var(--gap))",
  };
};

/** The cell both windows and the tray sit in: the second row. */
const TRAY_ROW = "lg:row-start-2";

/** A window's span on the grid, and its own card when the grid is stacked. */
const SLOT = cn(
  "relative overflow-hidden px-(--inset) pt-(--inset)",
  "max-lg:bg-muted max-lg:rounded-2xl max-lg:forced-colors:border",
  "lg:flex",
  TRAY_ROW
);

/**
 * The window itself: a Card with its own spacing, shadow and bottom edge
 * taken off, so it reads as a window running off the tray: a hairline on
 * the top and sides only, and only the top corners rounded. Below lg the
 * two never overlap, so the mask and the lift are switched off (the
 * classes win over the inline styles).
 */
const FRAME = cn(
  "w-full min-w-0 gap-0 overflow-hidden py-0 shadow-none",
  "border-foreground/[0.075] rounded-t-xl rounded-b-none border-x-[0.5px] border-t-[0.5px] border-b-0",
  "transition-[mask-position,-webkit-mask-position,transform] duration-500 ease-[cubic-bezier(0.4,0,0.2,1)] motion-reduce:transition-none",
  "max-lg:[mask-image:none]! max-lg:[transform:none]! max-lg:[-webkit-mask-image:none]!",
  "lg:flex-1"
);

/**
 * An arrow that shows when its link is pointed at: a fade, and a short
 * slide for those who take motion. It points with the reading direction.
 */
const Arrow = () => (
  <svg
    aria-hidden
    className="ms-1.5 inline size-[0.7em] align-baseline opacity-0 transition-[opacity,translate] duration-150 ease-out group-hover:translate-x-0 group-hover:opacity-100 group-focus-visible:translate-x-0 group-focus-visible:opacity-100 motion-safe:ltr:-translate-x-1 rtl:-scale-x-100 motion-safe:rtl:translate-x-1"
    fill="none"
    stroke="currentColor"
    strokeLinecap="round"
    strokeLinejoin="round"
    strokeWidth={1.4}
    viewBox="0 0 10 10"
  >
    <path d="M1 5h8M5.5 1.5 9 5 5.5 8.5" />
  </svg>
);

/** What sits above a window: its name and one line about it. */
export interface ContextColumn {
  /** The window's name, e.g. "Live context". */
  title: string;
  /** One sentence about it, in the muted colour. */
  body: string;
  /** Makes the title a link. */
  href?: string;
}

const Column = ({
  as: Title,
  body,
  className,
  href,
  title,
}: ContextColumn & { as: "h2" | "h3" | "h4"; className?: string }) => (
  <div className={cn("px-(--inset) max-lg:pb-5", className)}>
    <Title className="text-lg font-medium tracking-normal">
      {href ? (
        // The focus ring is the text colour, which stands out on every
        // surface of any theme (the theme's own ring colour is too pale
        // to count on). The pseudo-element makes the link 47px tall to
        // hit without moving anything.
        <a
          className="group focus-visible:outline-foreground relative rounded-sm after:absolute after:inset-x-0 after:-inset-y-3 focus-visible:outline-2 focus-visible:outline-offset-2"
          href={href}
        >
          {title}
          <Arrow />
        </a>
      ) : (
        title
      )}
    </Title>
    <p className="text-muted-foreground mt-1 max-w-[21rem] text-base leading-normal font-normal tracking-normal text-pretty">
      {body}
    </p>
  </div>
);

export interface ContextSectionProps extends Omit<
  ComponentProps<"section">,
  "children"
> {
  /** The section's headline. */
  heading?: ReactNode;
  /** The headline's level: 1 on a page it opens, 2 anywhere else. The two
   * column titles sit one level below it. */
  headingLevel?: 1 | 2 | 3;
  /** The copy above the chart, then above the chat. */
  columns?: [ContextColumn, ContextColumn];
  /** Which window starts in front: "chat" or "chart". With "chat" it answers
   * as the section comes into view; with "chart" the chart plays first, then
   * hands over to the chat. */
  defaultFront?: "chart" | "chat";
  /** The chart's own props: your changes, file count, snapshot day, sources
   * and title. Leave out for the demo. */
  chart?: FreshnessChartProps;
  /** The chat's own props: the question, the answer, its second line, the
   * file it names and the sources. Leave out for the demo. */
  chat?: SourceChatProps;
}

const COLUMNS: [ContextColumn, ContextColumn] = [
  {
    body: "Every change lands in your files as the work happens, so nothing drifts.",
    href: "#",
    title: "Live context",
  },
  {
    body: "Each answer names the file it read, who changed it and when.",
    href: "#",
    title: "Traceable answers",
  },
];

export const ContextSection = ({
  chart,
  chat,
  className,
  columns = COLUMNS,
  defaultFront = "chat",
  heading = "Answers are only as fresh as the context behind them",
  headingLevel = 2,
  ...props
}: ContextSectionProps) => {
  const Heading = `h${headingLevel}` as const;
  const columnTitle = `h${headingLevel + 1}` as "h2" | "h3" | "h4";
  const tray = useRef<HTMLDivElement>(null);
  const inView = useInView(tray, { amount: 0.4, once: true });
  // The chat's own slot: stacked, it can be a screen below the tray's top.
  const chatSlot = useRef<HTMLDivElement>(null);
  const chatSeen = useInView(chatSlot, { amount: 0.4, once: true });
  const reduce = useReducedMotion();
  const [front, setFront] = useState<Side>(defaultFront);
  const [stage, setStage] = useState(0);
  const [chatOn, setChatOn] = useState(false);
  // Set the first time the visitor points at a window: the story stops.
  const touched = useRef(false);
  // Whether focus last entered the chart's side from the keyboard.
  const fromKeys = useRef(false);

  useEffect(() => {
    if (!inView) {
      return;
    }
    // The chat is already in front (or nothing is to move): it starts now.
    if (reduce || defaultFront === "chat") {
      setChatOn(true);
      return;
    }
    const timers = [
      setTimeout(() => {
        if (!touched.current) {
          setStage(STAGE.pick);
        }
      }, STORY.pick),
      setTimeout(() => {
        if (!touched.current) {
          setStage(STAGE.handover);
          setFront("chat");
          setChatOn(true);
        }
      }, STORY.handover),
    ];
    return () => {
      for (const timer of timers) {
        clearTimeout(timer);
      }
    };
  }, [defaultFront, inView, reduce]);

  const bring = (side: Side) => {
    touched.current = true;
    setStage(STAGE.handover);
    setFront(side);
    if (side === "chat") {
      setChatOn(true);
    }
  };

  /** Focus on the chart or its title brings the chart forward. */
  const enterChart = (event: FocusEvent<HTMLDivElement>) => {
    fromKeys.current = event.target.matches(":focus-visible");
    bring("chart");
  };

  /**
   * The chat has nothing to tab to, so a keyboard user could never bring
   * it back: when their focus leaves the chart's side, the chat comes
   * forward. A pointer still on the chart keeps the chart.
   */
  const leaveChart = (event: FocusEvent<HTMLDivElement>) => {
    const side = event.currentTarget;
    if (
      fromKeys.current &&
      !side.contains(event.relatedTarget) &&
      !side.matches(":hover")
    ) {
      bring("chat");
    }
  };

  return (
    <section
      data-slot="context-section"
      className={cn(
        "bg-background text-foreground px-4 [--gap:0.75rem] [--inset:0.75rem] sm:px-6 sm:[--inset:1.25rem]",
        className
      )}
      {...props}
    >
      {/* 72rem of columns, a gap of padding each side, and the two rails:
          twelve 85px columns at full width. */}
      <div className="border-foreground/5 mx-auto max-w-[calc(72rem+2*var(--gap)+2px)] border-x px-(--gap) pb-20 lg:pb-28">
        <Heading className="max-w-[36rem] px-(--inset) pt-20 pb-10 text-[1.75rem] leading-[calc(34/28)] font-normal tracking-[-0.02em] text-balance lg:pt-28 lg:pb-14 lg:text-4xl lg:leading-[calc(42/36)]">
          {heading}
        </Heading>

        {/* The padding and matching negative margin give the top row's
            focus rings room inside the clip. */}
        <div
          ref={tray}
          className="isolate lg:-mt-3 lg:grid lg:grid-cols-12 lg:gap-x-(--gap) lg:gap-y-11 lg:overflow-hidden lg:rounded-b-2xl lg:pt-3"
        >
          {/* The tray, and above everything its hairline edge, drawn as a
              separate layer so the windows never cover it. */}
          <div
            className={cn(
              "bg-muted col-span-full rounded-2xl max-lg:hidden",
              TRAY_ROW
            )}
          />
          <div
            className={cn(
              "ring-foreground/[0.075] pointer-events-none relative z-50 col-span-full rounded-2xl ring-[0.5px] ring-inset max-lg:hidden forced-colors:border",
              TRAY_ROW
            )}
          />

          {/* A side is a column and its window. The wrappers have no box
              of their own (the grid still places their children); they
              only listen for focus. */}
          <div className="contents" onBlur={leaveChart} onFocus={enterChart}>
            <Column
              {...columns[0]}
              as={columnTitle}
              className="lg:col-span-5 lg:col-start-1 lg:row-start-1"
            />
            <div
              className={cn(
                SLOT,
                "max-lg:mb-12 lg:col-span-7 lg:col-start-1",
                front === "chart" ? "lg:z-2" : "lg:z-1"
              )}
              onPointerEnter={() => bring("chart")}
            >
              <Card
                className={FRAME}
                style={standing("chart", front === "chart")}
              >
                <FreshnessChart
                  pick={stage === STAGE.pick ? DEMO_PICK : undefined}
                  play={inView}
                  quiet={front !== "chart"}
                  {...chart}
                />
              </Card>
            </div>
          </div>

          <div className="contents" onFocus={() => bring("chat")}>
            <Column
              {...columns[1]}
              as={columnTitle}
              className="lg:col-span-5 lg:col-start-7 lg:row-start-1"
            />
            <div
              ref={chatSlot}
              className={cn(
                SLOT,
                "lg:col-span-6 lg:col-start-7",
                front === "chat" ? "lg:z-2" : "lg:z-1"
              )}
              onPointerEnter={() => bring("chat")}
            >
              <Card
                className={FRAME}
                style={standing("chat", front === "chat")}
              >
                <SourceChat play={chatOn && chatSeen} {...chat} />
              </Card>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default ContextSection;

"use client";

import {
  Calendar03Icon,
  FileSyncIcon,
  GithubIcon,
  GoogleDriveIcon,
  NotionIcon,
  SlackIcon,
} from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import type { IconSvgElement } from "@hugeicons/react";
import NumberFlow from "@number-flow/react";
import {
  AnimatePresence,
  MotionConfig,
  animate,
  motion,
  useMotionValue,
  useReducedMotion,
  useTransform,
} from "motion/react";
import type { MotionValue } from "motion/react";
import { useEffect, useId, useMemo, useRef, useState } from "react";
import type {
  ComponentProps,
  KeyboardEvent,
  PointerEvent,
  ReactNode,
} from "react";

import { Card } from "@/components/ui/card";
import { cn } from "@/lib/utils";

/* ─────────────────────────────────────────────────────────────────────────
 * Context freshness. A step chart for one question: how much of what a
 * team knows is still true? Two lines start together on the
 * day a snapshot was built. The snapshot's line steps down every time a file
 * changes for the first time (it never hears about it); the live line holds.
 * The dotted field between them is the drift. Under the chart, one lane per
 * source carries a tick for every change. Point at any moment (or step
 * through with the arrow keys) and the change opens as a diff: the line the
 * snapshot still has in red, the line that is true now in green.
 *
 * ANIMATION STORYBOARD
 *
 *    play     a sweep reveals the timeline left to right (1.4s, ease-in-
 *             out): the snapshot line steps down, the ticks appear as it
 *             passes, and the snapshot's number counts down with it
 *    settle   over the last 15% of the sweep the line ends, their labels
 *             and each source's count fade in
 *    live     both line ends pulse twice: a ring grows out of each dot
 *             and fades, 2s a pulse, together. Then they rest: anything
 *             that blinks for more than five seconds needs a way to stop
 *             it. They pulse twice again whenever the chart comes back to
 *             attention: brought forward, or focused
 *    point    a crosshair snaps to the nearest change, its lane lights up,
 *             the rest dim (150ms), and the change opens as a diff (120ms
 *             in); moving on glides both to the next change (0.18s spring)
 *
 * With reduced motion it is simply there, and the crosshair jumps.
 * ───────────────────────────────────────────────────────────────────────── */

/** One change to one file. */
export interface ContextChange {
  /** A stable id for the change. */
  id: string;
  /** When it happened. */
  at: Date | string | number;
  /** The file that changed, e.g. "policies/refunds.md". */
  file: string;
  /** Where the change came from. Names its lane. */
  source: string;
  /** Who made it. */
  by: string;
  /** The line as the snapshot has it. */
  before: string;
  /** The line as it is now. */
  after: string;
}

/** A place changes come from: one lane under the chart. */
export interface ContextSource {
  /** The source's name. A change belongs to the lane whose name matches
   * its `source`. */
  name: string;
  /** Its icon: any icon from the Hugeicons core-free-icons package. */
  icon: IconSvgElement;
}

export interface FreshnessChartProps extends Omit<
  ComponentProps<"div">,
  "children" | "title"
> {
  /** Every change since the snapshot. Leave out for the demo. */
  changes?: ContextChange[];
  /** How many files are tracked in all. */
  files?: number;
  /** The share still current with live updates, in percent. */
  live?: number;
  /** The day the snapshot was built. */
  snapshot?: Date | string | number;
  /** Today: where the timeline ends. */
  now?: Date | string | number;
  /** The lanes, top first. */
  sources?: ContextSource[];
  /** The window's title. */
  title?: string;
  /** A BCP 47 locale for the dates. */
  locale?: string;
  /** Draws the chart in. Flip it to true when the chart is in view. */
  play?: boolean;
  /** A change to show while nothing is pointed at (for a guided demo). */
  pick?: string;
  /** Fades the right gutter (the lines' end labels) out at lg and up, for
   * while the window beside the chart covers it. */
  quiet?: boolean;
}

/* ─────────────────────────────────────────────────────────────────────────
 * Demo: 128 files, a snapshot from January, 212 changes since.
 * ───────────────────────────────────────────────────────────────────────── */

export const DEMO_SNAPSHOT = new Date(2026, 0, 12, 9);
export const DEMO_NOW = new Date(2026, 10, 13, 9);
export const DEMO_FILES = 128;

/** The change the demo points at. The chat's answer cites the same file. */
export const DEMO_PICK = "refunds";

export const DEMO_SOURCES: ContextSource[] = [
  { icon: SlackIcon, name: "Slack" },
  { icon: NotionIcon, name: "Notion" },
  { icon: GoogleDriveIcon, name: "Drive" },
  { icon: GithubIcon, name: "GitHub" },
];

const FOLDERS = [
  "policies",
  "pricing",
  "product",
  "security",
  "people",
  "sales",
  "support",
  "finance",
];
const NAMES = [
  "overview",
  "playbook",
  "tiers",
  "roadmap",
  "onboarding",
  "sla",
  "escalation",
  "glossary",
  "faq",
  "limits",
];
const TEAMS = [
  "Support ops",
  "Sales ops",
  "Product",
  "Security",
  "People",
  "Finance",
];
const EDITS = [
  ["Reply within 5 days", "Reply within 2 days"],
  ["Free plan: 3 seats", "Free plan: 5 seats"],
  ["SSO on Enterprise only", "SSO on Team and up"],
  ["Reviewed every quarter", "Reviewed every month"],
  ["Tier 2 after 48 hours", "Tier 2 after 24 hours"],
  ["Ships in Q3", "Ships in Q4"],
  ["Discount cap: 20%", "Discount cap: 15%"],
  ["Owner: Priya", "Owner: Tomás"],
];

/** A small seeded random, so the demo is the same on every load. */
const seeded = (seed: number) => {
  let state = seed;
  return () => {
    state = (state * 9301 + 49_297) % 233_280;
    return state / 233_280;
  };
};

/** 75 files changed at least once, 212 changes in all. */
const demoChanges = (): ContextChange[] => {
  const random = seeded(19);
  const start = DEMO_SNAPSHOT.getTime();
  const span = DEMO_NOW.getTime() - start;
  const pickOf = <T,>(list: T[]) =>
    list[Math.floor(random() * list.length)] as T;
  const paths = FOLDERS.flatMap((folder) =>
    NAMES.map((name) => `${folder}/${name}.md`)
  );
  const detail = () => {
    const [before, after] = pickOf(EDITS);
    return {
      after: after ?? "",
      before: before ?? "",
      by: pickOf(TEAMS),
      source: pickOf(DEMO_SOURCES).name,
    };
  };
  // The first change to each of 74 files, a little denser early on.
  const firsts = paths.slice(0, 74).map(
    (file, i): ContextChange => ({
      ...detail(),
      at: start + span * (0.01 + 0.97 * random() ** 1.15),
      file,
      id: `f${i}`,
    })
  );
  // Then 137 more edits to files that had already changed.
  const repeats = Array.from({ length: 137 }, (_, i): ContextChange => {
    const earlier = pickOf(firsts);
    const from = new Date(earlier.at).getTime();
    return {
      ...detail(),
      at: from + (start + span - from) * (0.04 + 0.95 * random()),
      file: earlier.file,
      id: `r${i}`,
    };
  });
  return [
    ...firsts,
    ...repeats,
    {
      after: "Refunds within 30 days",
      at: new Date(2026, 5, 9, 11),
      before: "Refunds within 14 days",
      by: "Support ops",
      file: "policies/refunds.md",
      id: DEMO_PICK,
      source: "Notion",
    },
  ];
};

const DEMO = demoChanges();

/* ─────────────────────────────────────────────────────────────────────────
 * Motion and layout. Every value that sets a beat or a size lives here.
 * ───────────────────────────────────────────────────────────────────────── */

const MOTION = {
  /** The tooltip and crosshair glide between changes, in seconds. */
  glide: 0.18,
  /** One pulse of the line ends, in seconds: a ring out, then a rest. */
  pulse: 2,
  /** How many pulses in a row. Two is 4s: under the 5s that would need a
   * pause control. */
  pulses: 2,
  /** The draw-in sweep across the timeline, in seconds. */
  sweep: 1.4,
  /** The tooltip fades in, in seconds. */
  tipIn: 0.12,
  /** And out, quicker. */
  tipOut: 0.1,
} as const;

const EASE_IN_OUT = [0.65, 0, 0.35, 1] as const;
const EASE_OUT = [0.23, 1, 0.32, 1] as const;
const GLIDE = {
  bounce: 0,
  type: "spring",
  visualDuration: MOTION.glide,
} as const;

/** The two headline numbers. */
const HERO = "text-3xl font-semibold tracking-tight tabular-nums";

/** The change card's size and its gap from the crosshair, in px. */
const TIP = { gap: 16, width: 232 } as const;

/** The plot's measurements, in px. */
const PLOT = {
  /** Room under the time axis for its labels. */
  axis: 26,
  /** The chart's height. */
  chart: 128,
  /** The gap between the chart and the first lane. */
  gap: 14,
  /** A mono label's line height: the label column is laid out from it. */
  label: 12,
  /** One lane's height. */
  lane: 22,
  /** Room above the chart, so a line's end ring isn't cut. */
  top: 10,
} as const;

/** The value axis: where the gridlines and their labels sit, in percent. */
const GRID = [100, 50, 0];

/** The colours, light then dark. Retune them on the chart or a parent. */
const COLORS = cn(
  "[--ctx-live:oklch(0.55_0.15_152)] [--ctx-stale:oklch(0.58_0.2_25)]",
  "dark:[--ctx-live:oklch(0.79_0.17_152)] dark:[--ctx-stale:oklch(0.7_0.19_22)]"
);

const CSS = `
@keyframes ctx-ring { 0% { opacity: .5; transform: scale(1) } 70%, 100% { opacity: 0; transform: scale(3) } }
.ctx-ring { transform-box: fill-box; transform-origin: center; opacity: 0; animation: ctx-ring ${MOTION.pulse}s cubic-bezier(0,0,.2,1) ${MOTION.pulses}; }
@media (prefers-reduced-motion: reduce) { .ctx-ring { animation: none; opacity: 0; } }
`;

/* ─────────────────────────────────────────────────────────────────────────
 * The numbers.
 * ───────────────────────────────────────────────────────────────────────── */

const toTime = (value: Date | string | number) => new Date(value).getTime();

/** A change with its time and what it did to the snapshot worked out. */
interface Change extends ContextChange {
  /** The first change to its file: the moment the snapshot lost it. */
  first: boolean;
  /** The share of files the snapshot still has right, after this change. */
  share: number;
  time: number;
}

const useModel = ({
  changes,
  files,
  now,
  snapshot,
}: Required<Pick<FreshnessChartProps, "files" | "now" | "snapshot">> & {
  changes: ContextChange[];
}) =>
  useMemo(() => {
    const start = toTime(snapshot);
    const stop = Math.max(toTime(now), start + 1);
    const changed = new Set<string>();
    const all = changes
      .map((change) => ({ ...change, time: toTime(change.at) }))
      .filter((change) => change.time >= start && change.time <= stop)
      .toSorted((a, b) => a.time - b.time)
      .map((change): Change => {
        const first = !changed.has(change.file);
        changed.add(change.file);
        return {
          ...change,
          first,
          share: ((files - changed.size) / files) * 100,
        };
      });
    return { all, share: all.at(-1)?.share ?? 100, start, stop };
  }, [changes, files, now, snapshot]);

type Model = ReturnType<typeof useModel>;

const useFormat = (locale?: string) =>
  useMemo(() => {
    const date = new Intl.DateTimeFormat(locale, {
      day: "numeric",
      month: "short",
    });
    const month = new Intl.DateTimeFormat(locale, { month: "short" });
    const list = new Intl.ListFormat(locale, { type: "conjunction" });
    return {
      date: (time: number) => date.format(time),
      list: (items: string[]) => list.format(items),
      month: (time: number) => month.format(time),
    };
  }, [locale]);

type Format = ReturnType<typeof useFormat>;

/* ─────────────────────────────────────────────────────────────────────────
 * Geometry. The plot is the middle column only: x runs its full width.
 * ───────────────────────────────────────────────────────────────────────── */

const LANES_TOP = PLOT.top + PLOT.chart + PLOT.gap;

const useGeometry = (model: Model, lanes: number, width: number) =>
  useMemo(() => {
    const lanesBottom = LANES_TOP + lanes * PLOT.lane;
    return {
      height: lanesBottom + PLOT.axis,
      laneY: (index: number) => LANES_TOP + index * PLOT.lane + PLOT.lane / 2,
      lanesBottom,
      width,
      x: (time: number) =>
        ((time - model.start) / (model.stop - model.start)) * width,
      y: (share: number) => PLOT.top + ((100 - share) / 100) * PLOT.chart,
    };
  }, [lanes, model, width]);

type Geometry = ReturnType<typeof useGeometry>;

/** The snapshot's share as a step line: down one file at every first change. */
const stepPath = (model: Model, geo: Geometry) => {
  let d = `M0,${geo.y(100)}`;
  for (const change of model.all) {
    if (change.first) {
      d += `H${geo.x(change.time)}V${geo.y(change.share)}`;
    }
  }
  return `${d}H${geo.width}`;
};

/** The first day of every month inside the timeline. */
const monthsOf = (model: Model) => {
  const months: number[] = [];
  const date = new Date(model.start);
  let time = new Date(date.getFullYear(), date.getMonth() + 1, 1).getTime();
  while (time < model.stop) {
    months.push(time);
    const next = new Date(time);
    time = new Date(next.getFullYear(), next.getMonth() + 1, 1).getTime();
  }
  return months;
};

/* ─────────────────────────────────────────────────────────────────────────
 * Pieces.
 * ───────────────────────────────────────────────────────────────────────── */

/** The value grid, and the months along the bottom. */
const Axes = ({
  format,
  geo,
  model,
}: {
  format: Format;
  geo: Geometry;
  model: Model;
}) => {
  const axisY = geo.lanesBottom + 6;
  const months = monthsOf(model);
  // A label every month, or every second or third when they'd touch, and
  // none that would run into Today at the end.
  const gap = months.length > 1 ? geo.width / (months.length + 1) : geo.width;
  const stride = Math.max(1, Math.ceil(34 / Math.max(gap, 1)));
  const labelled = months.filter(
    (time, i) => i % stride === 0 && geo.width - geo.x(time) > 44
  );
  return (
    <g className="font-mono text-[0.625rem]">
      {GRID.map((value) => (
        // Plain hairlines: the dots belong to the data.
        <line
          key={value}
          className={value === 0 ? "stroke-border" : "stroke-border/50"}
          x1={0}
          x2={geo.width}
          y1={geo.y(value)}
          y2={geo.y(value)}
        />
      ))}
      {months.map((time) => (
        <line
          key={time}
          className="stroke-muted-foreground/40"
          x1={geo.x(time)}
          x2={geo.x(time)}
          y1={axisY}
          y2={axisY + 4}
        />
      ))}
      {labelled.map((time) => (
        <text
          key={time}
          className="fill-muted-foreground"
          textAnchor="middle"
          x={geo.x(time)}
          y={axisY + 16}
        >
          {format.month(time)}
        </text>
      ))}
      <line
        className="stroke-foreground/20"
        x1={geo.width}
        x2={geo.width}
        y1={PLOT.top}
        y2={axisY + 5}
      />
      <text
        className="fill-foreground"
        textAnchor="end"
        x={geo.width}
        y={axisY + 16}
      >
        Today
      </text>
    </g>
  );
};

/** One source's lane: a track from its first change to its last, a tick each. */
const Lane = ({
  active,
  dim,
  geo,
  index,
  model,
  source,
}: {
  active?: string;
  dim: boolean;
  geo: Geometry;
  index: number;
  model: Model;
  source: string;
}) => {
  const changes = model.all.filter((change) => change.source === source);
  const y = geo.laneY(index);
  const [first] = changes;
  const last = changes.at(-1);
  if (!(first && last)) {
    return null;
  }
  return (
    <g
      className={cn(
        "transition-opacity duration-150 ease-out",
        dim && "opacity-35"
      )}
    >
      <line
        className="stroke-muted-foreground/20"
        strokeLinecap="round"
        strokeWidth={2}
        x1={geo.x(first.time)}
        x2={geo.x(last.time)}
        y1={y}
        y2={y}
      />
      {changes.map((change) => {
        // A file's first change is the one the snapshot misses: taller,
        // and in the snapshot's colour. Later edits to it are quiet.
        const height = (change.first ? 12 : 7) + (change.id === active ? 4 : 0);
        return (
          <rect
            key={change.id}
            className={
              change.first ? "fill-(--ctx-stale)" : "fill-muted-foreground/45"
            }
            height={height}
            rx={1}
            width={2}
            x={geo.x(change.time) - 1}
            y={y - height / 2}
          />
        );
      })}
    </g>
  );
};

/** The change under the pointer, as a diff of one line. */
const ChangeCard = ({
  change,
  format,
  width,
}: {
  change: Change;
  format: Format;
  width: number;
}) => (
  <Card
    className="bg-popover text-popover-foreground gap-0 overflow-hidden rounded-lg border py-0 shadow-lg"
    style={{ width }}
  >
    <div className="flex items-baseline justify-between gap-3 px-3 pt-2.5">
      <span className="min-w-0 font-mono text-xs font-medium break-words">
        {change.file}
      </span>
      <span className="text-muted-foreground shrink-0 font-mono text-[0.6875rem] whitespace-nowrap">
        {format.date(change.time)}
      </span>
    </div>
    <p className="text-muted-foreground px-3 pt-0.5 pb-2.5 text-xs">
      {change.by} · {change.source}
    </p>
    <div className="border-t font-mono text-xs">
      <div className="flex items-center gap-2 bg-(--ctx-stale)/10 px-3 py-1.5">
        <span className="text-(--ctx-stale)">−</span>
        <span className="min-w-0 flex-1 break-words">{change.before}</span>
      </div>
      <div className="flex items-center gap-2 bg-(--ctx-live)/10 px-3 py-1.5">
        <span className="text-(--ctx-live)">+</span>
        <span className="min-w-0 flex-1 break-words">{change.after}</span>
      </div>
    </div>
  </Card>
);

/** The crosshair at a change, with a mark on each line where it crosses. */
const Crosshair = ({
  change,
  geo,
  live,
}: {
  change: Change;
  geo: Geometry;
  live: number;
}) => {
  const reduce = useReducedMotion();
  const transition = reduce ? { duration: 0 } : GLIDE;
  return (
    <motion.g
      animate={{ x: geo.x(change.time) }}
      initial={false}
      transition={transition}
    >
      <line
        className="stroke-foreground/30"
        x1={0}
        x2={0}
        y1={PLOT.top}
        y2={geo.lanesBottom}
      />
      {[
        { className: "fill-(--ctx-live)", value: live },
        { className: "fill-(--ctx-stale)", value: change.share },
      ].map((mark) => (
        <motion.circle
          key={mark.className}
          animate={{ cy: geo.y(mark.value) }}
          className={cn(mark.className, "stroke-card")}
          cx={0}
          initial={false}
          r={3.5}
          strokeWidth={2}
          transition={transition}
        />
      ))}
    </motion.g>
  );
};

/**
 * Follows an element's width, and the room its parent leaves on each side
 * of it (here: the label column before the plot and the gutter after it).
 */
const useWidth = () => {
  const ref = useRef<HTMLDivElement>(null);
  const [size, setSize] = useState({ after: 0, before: 0, width: 0 });
  useEffect(() => {
    const element = ref.current;
    const parent = element?.parentElement;
    if (!(element && parent)) {
      return;
    }
    const observer = new ResizeObserver(() => {
      const box = element.getBoundingClientRect();
      const around = parent.getBoundingClientRect();
      setSize({
        after: Math.round(around.right - box.right),
        before: Math.round(box.left - around.left),
        width: Math.round(box.width),
      });
    });
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  return { ref, ...size };
};

/** `progress` runs 0 → 1 across the sweep, once `play` turns true. */
const useDrawIn = (play: boolean) => {
  const reduce = useReducedMotion();
  const progress = useMotionValue(0);
  const [drawn, setDrawn] = useState(false);
  useEffect(() => {
    if (!play) {
      return;
    }
    if (reduce) {
      progress.set(1);
      setDrawn(true);
      return;
    }
    const controls = animate(progress, 1, {
      duration: MOTION.sweep,
      ease: EASE_IN_OUT,
      onComplete: () => setDrawn(true),
    });
    return () => controls.stop();
  }, [play, progress, reduce]);
  return { drawn, progress };
};

/** Which change sits nearest a point along the plot, in px. */
const nearest = (changes: Change[], geo: Geometry, px: number) => {
  let best: Change | undefined;
  let gap = Number.POSITIVE_INFINITY;
  for (const change of changes) {
    const distance = Math.abs(geo.x(change.time) - px);
    if (distance < gap) {
      best = change;
      gap = distance;
    }
  }
  return best;
};

/** A slider's keys: up and right go on, down and left back, pages by ten. */
const KEY_STEP: Record<string, number> = {
  ArrowDown: -1,
  ArrowLeft: -1,
  ArrowRight: 1,
  ArrowUp: 1,
  PageDown: -10,
  PageUp: 10,
};

/** Where a key takes the picked change: an index, "clear", or nowhere. */
const keyTarget = (key: string, index: number, last: number) => {
  const step = KEY_STEP[key];
  if (step !== undefined) {
    // Nothing picked yet: the first step lands on the first (or last).
    const origin = index === -1 && step < 0 ? last + 1 : index;
    return Math.min(last, Math.max(0, origin + step));
  }
  if (key === "Home") {
    return 0;
  }
  if (key === "End") {
    return last;
  }
  return key === "Escape" ? "clear" : undefined;
};

/** The counting numbers land with the sweep. */
const COUNT = {
  duration: MOTION.sweep * 1000,
  easing: "cubic-bezier(0.65, 0, 0.35, 1)",
};

/** One fact under the numbers: an icon and a few words. */
const Fact = ({
  children,
  icon,
}: {
  children: ReactNode;
  icon: IconSvgElement;
}) => (
  <span className="inline-flex items-center gap-1.5">
    <HugeiconsIcon
      absoluteStrokeWidth
      aria-hidden
      className="shrink-0"
      icon={icon}
      size={14}
      strokeWidth={1.25}
    />
    <span>{children}</span>
  </span>
);

/**
 * The window's title and the two numbers the whole section is about, side
 * by side: the live one holds, the snapshot's counts down with the sweep
 * and follows the crosshair while a change is picked.
 */
const Header = ({
  active,
  format,
  live,
  locale,
  model,
  play,
  title,
}: {
  active?: Change;
  format: Format;
  live: number;
  locale: string;
  model: Model;
  play: boolean;
  title: string;
}) => (
  <div className="px-5 pt-4">
    <p className="py-1.5 text-base font-normal text-pretty">{title}</p>
    <div className="mt-1 flex flex-wrap items-baseline gap-x-5 gap-y-1">
      <p className="flex items-baseline gap-x-2">
        <span className={HERO}>{live}%</span>
        <span className="text-muted-foreground text-sm">live</span>
      </p>
      <p className="flex items-baseline gap-x-2">
        <NumberFlow
          animated={!active}
          // The line height is pinned: as served the element takes its own
          // (1), once running the text size's (1.2), and the difference
          // would make the window 6px taller a moment after it loads.
          className={cn(HERO, "text-muted-foreground leading-9!")}
          locales={locale}
          spinTiming={COUNT}
          suffix="%"
          transformTiming={COUNT}
          value={Math.round(active?.share ?? (play ? model.share : 100))}
        />
        <span className="text-muted-foreground text-sm">snapshot</span>
      </p>
    </div>
    {/* The facts under the numbers, the way a repository lists its
        commits: how many changes, and since when. While a change is picked
        both follow the crosshair: the changes up to it, and its date. */}
    <div className="text-muted-foreground mt-2 flex flex-wrap items-center gap-x-4 gap-y-1 text-xs">
      <Fact icon={FileSyncIcon}>
        <span className="text-foreground tabular-nums">
          {active ? model.all.indexOf(active) + 1 : model.all.length}
        </span>{" "}
        changes
      </Fact>
      <Fact icon={Calendar03Icon}>
        {active
          ? `As of ${format.date(active.time)}`
          : `Since ${format.date(model.start)}`}
      </Fact>
    </div>
  </div>
);

/** The left column: the value axis's labels, then each source's name. */
const Labels = ({
  active,
  sources,
}: {
  active?: Change;
  sources: ContextSource[];
}) => (
  <div
    aria-hidden
    className="text-muted-foreground font-mono text-[0.625rem] leading-3"
  >
    {/* Three labels spread over the chart's height, each centred on its
        gridline: the box starts and ends half a line outside the chart. */}
    <div
      className="flex flex-col justify-between"
      style={{
        height: PLOT.top + PLOT.chart + PLOT.label / 2,
        paddingTop: PLOT.top - PLOT.label / 2,
      }}
    >
      {GRID.map((value) => (
        <span key={value}>{value}%</span>
      ))}
    </div>
    <div style={{ height: PLOT.gap - PLOT.label / 2 }} />
    {sources.map((source) => (
      <div
        key={source.name}
        className={cn(
          "flex items-center gap-1.5 transition-opacity duration-150 ease-out",
          active?.source === source.name && "text-foreground",
          active && active.source !== source.name && "opacity-35"
        )}
        style={{ height: PLOT.lane }}
      >
        <HugeiconsIcon
          absoluteStrokeWidth
          icon={source.icon}
          size={12}
          strokeWidth={1}
        />
        {source.name}
      </div>
    ))}
  </div>
);

/**
 * The right gutter: each line named at its end, each source's count beside
 * its lane. It is the strip the chat window covers when it comes forward,
 * so nothing is said only here.
 */
const Gutter = ({
  active,
  geo,
  live,
  model,
  quiet,
  settled,
  sources,
}: {
  active?: Change;
  geo: Geometry;
  live: number;
  model: Model;
  quiet: boolean;
  settled: MotionValue<number>;
  sources: ContextSource[];
}) => {
  const liveY = geo.y(live);
  const ends = [
    { className: "text-(--ctx-live)", text: `Live ${live}%`, y: liveY },
    {
      className: "text-(--ctx-stale)",
      text: `Snapshot ${Math.round(model.share)}%`,
      // Nudged down when the two lines end close together.
      y: Math.max(geo.y(model.share), liveY + 13),
    },
  ];
  return (
    // Two fades, one inside the other: the outer one for `quiet`, the
    // inner one for the draw-in.
    <div
      aria-hidden
      className={cn(
        "relative font-mono text-[0.625rem] leading-3 transition-opacity duration-300 ease-out max-sm:hidden",
        // Only where the section's two windows overlap: stacked, nothing
        // covers the gutter.
        quiet && "lg:opacity-0"
      )}
    >
      <motion.div className="absolute inset-0" style={{ opacity: settled }}>
        {ends.map((end) => (
          <span
            key={end.text}
            className={cn(
              "absolute left-0 -translate-y-1/2 whitespace-nowrap transition-opacity duration-150",
              end.className,
              active && "opacity-0"
            )}
            style={{ top: end.y }}
          >
            {end.text}
          </span>
        ))}
        {sources.map((source, i) => (
          <span
            key={source.name}
            className={cn(
              "text-muted-foreground absolute right-0 -translate-y-1/2 tabular-nums transition-opacity duration-150 ease-out",
              active?.source === source.name && "text-foreground",
              active && active.source !== source.name && "opacity-35"
            )}
            style={{ top: geo.laneY(i) }}
          >
            {model.all.filter((change) => change.source === source.name).length}
          </span>
        ))}
      </motion.div>
    </div>
  );
};

/**
 * The timeline's drawing: the grid, the two lines with the drift between
 * them, the lanes, the line ends, and the crosshair when a change is picked.
 */
const Timeline = ({
  active,
  beat,
  format,
  geo,
  live,
  model,
  progress,
  settled,
  sources,
}: {
  active?: Change;
  /** Counts up to play the line ends' pulse again; 0 before the first. */
  beat: number;
  format: Format;
  geo: Geometry;
  live: number;
  model: Model;
  progress: MotionValue<number>;
  settled: MotionValue<number>;
  sources: ContextSource[];
}) => {
  const raw = useId();
  const id = raw.replaceAll(/[^a-zA-Z0-9]/gu, "");
  const sweep = useTransform(progress, (p) => p * geo.width);
  const line = stepPath(model, geo);
  const liveY = geo.y(live);
  return (
    // Time runs left to right here in every language.
    <svg
      aria-hidden
      className="block overflow-visible"
      direction="ltr"
      height={geo.height}
      width={geo.width}
    >
      <defs>
        <pattern
          height={4}
          id={`${id}-drift`}
          patternUnits="userSpaceOnUse"
          width={4}
        >
          <circle cx={2} cy={2} fill="var(--ctx-stale)" opacity={0.6} r={0.7} />
        </pattern>
        <clipPath id={`${id}-sweep`}>
          <motion.rect height={geo.height} width={sweep} x={0} y={0} />
        </clipPath>
      </defs>
      <Axes format={format} geo={geo} model={model} />
      <g clipPath={`url(#${id}-sweep)`}>
        {/* The drift: everything between the two lines. */}
        <path d={`${line}V${liveY}H0Z`} fill={`url(#${id}-drift)`} />
        <path
          className="stroke-(--ctx-live)"
          d={`M0,${liveY}H${geo.width}`}
          fill="none"
          strokeWidth={1.75}
        />
        <path
          className="stroke-(--ctx-stale)"
          d={line}
          fill="none"
          strokeLinejoin="round"
          strokeWidth={1.75}
        />
        {sources.map((source, i) => (
          <Lane
            key={source.name}
            active={active?.id}
            dim={Boolean(active) && active?.source !== source.name}
            geo={geo}
            index={i}
            model={model}
            source={source.name}
          />
        ))}
      </g>
      {/* The line ends, each a dot with a ring that pulses out of it. The
          ring is a new element on every beat: that is what replays it. */}
      <motion.g style={{ opacity: active ? 0 : settled }}>
        {[
          { className: "fill-(--ctx-live)", y: liveY },
          { className: "fill-(--ctx-stale)", y: geo.y(model.share) },
        ].map((end) => (
          <g key={end.className} className={end.className}>
            {beat > 0 && (
              <circle
                key={beat}
                className="ctx-ring"
                cx={geo.width}
                cy={end.y}
                r={3}
              />
            )}
            <circle cx={geo.width} cy={end.y} r={3} />
          </g>
        ))}
      </motion.g>
      {active && <Crosshair change={active} geo={geo} live={live} />}
    </svg>
  );
};

/** The plot's input: pointer, touch and keys all pick a change. */
const Scrubber = ({
  active,
  enabled,
  format,
  geo,
  model,
  onAttend,
  onPick,
}: {
  active?: Change;
  enabled: boolean;
  format: Format;
  geo: Geometry;
  model: Model;
  /** The plot took focus. */
  onAttend: () => void;
  onPick: (id?: string) => void;
}) => {
  const index = active ? model.all.indexOf(active) : -1;
  const onPointer = (event: PointerEvent<HTMLDivElement>) => {
    if (!enabled) {
      return;
    }
    const box = event.currentTarget.getBoundingClientRect();
    onPick(nearest(model.all, geo, event.clientX - box.left)?.id);
  };
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const target = keyTarget(event.key, index, model.all.length - 1);
    if (target === undefined) {
      return;
    }
    if (target === "clear") {
      onPick();
      return;
    }
    event.preventDefault();
    onPick(model.all[target]?.id);
  };
  return (
    <div
      aria-label="Changes since the snapshot"
      aria-valuemax={model.all.length}
      aria-valuemin={1}
      aria-valuenow={index + 1 || 1}
      aria-valuetext={
        active
          ? `${format.date(active.time)}: ${active.file}, changed by ${active.by} from "${active.before}" to "${active.after}". Snapshot at ${Math.round(active.share)}%.`
          : "Use the arrow keys to step through the changes"
      }
      // The focus ring is the text colour, which stands out on every
      // surface of any theme, and an outline still shows when the system
      // forces its own colours (a shadow ring would not).
      className="focus-visible:outline-foreground absolute inset-0 rounded-md focus-visible:outline-2 focus-visible:outline-offset-2"
      onBlur={() => onPick()}
      onFocus={onAttend}
      onKeyDown={onKeyDown}
      onPointerDown={onPointer}
      onPointerLeave={() => onPick()}
      onPointerMove={onPointer}
      role="slider"
      style={{ touchAction: "pan-y" }}
      tabIndex={model.all.length > 0 ? 0 : -1}
    />
  );
};

/**
 * Where the change card sits: beside the crosshair, flipped to its left
 * when the right has no room for it. It may run over the label column and
 * the gutter (`room`, in px each side of the plot), never past them.
 */
const tipPlace = (
  geo: Geometry,
  room: { after: number; before: number },
  change?: Change
) => {
  const cross = change ? geo.x(change.time) : 0;
  const width = Math.min(TIP.width, geo.width);
  const last = geo.width + room.after - width;
  const beside =
    cross + TIP.gap > last ? cross - TIP.gap - width : cross + TIP.gap;
  return { width, x: Math.max(-room.before, Math.min(beside, last)) };
};

/* ─────────────────────────────────────────────────────────────────────────
 * The chart.
 * ───────────────────────────────────────────────────────────────────────── */

export const FreshnessChart = ({
  changes = DEMO,
  className,
  files = DEMO_FILES,
  live = 99,
  locale = "en-GB",
  now = DEMO_NOW,
  pick,
  play = true,
  quiet = false,
  snapshot = DEMO_SNAPSHOT,
  sources = DEMO_SOURCES,
  title = "Context freshness",
  ...props
}: FreshnessChartProps) => {
  const model = useModel({ changes, files, now, snapshot });
  const format = useFormat(locale);
  const { after, before, ref: plotRef, width } = useWidth();
  const geo = useGeometry(model, sources.length, width);
  const { drawn, progress } = useDrawIn(play);
  const settled = useTransform(progress, [0.85, 1], [0, 1]);
  const [pointed, setPointed] = useState<string>();
  const shown = pointed ?? pick;
  const active = model.all.find((change) => change.id === shown);
  const tip = tipPlace(geo, { after, before }, active);
  const measured = width > 0;

  // The line ends pulse when the chart is drawn, and again each time it
  // comes back to attention: brought forward (no longer quiet) or focused.
  const [beat, setBeat] = useState(0);
  const last = useRef({ drawn: false, quiet });
  useEffect(() => {
    const was = last.current;
    last.current = { drawn, quiet };
    const justDrawn = drawn && !was.drawn;
    const cameForward = drawn && was.quiet && !quiet;
    if (justDrawn || cameForward) {
      setBeat((count) => count + 1);
    }
  }, [drawn, quiet]);

  // The card opens on hover, so Escape has to close it wherever focus is.
  useEffect(() => {
    if (!pointed) {
      return;
    }
    const onKey = (event: { key: string }) => {
      if (event.key === "Escape") {
        setPointed(undefined);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [pointed]);

  return (
    <MotionConfig reducedMotion="user">
      <div
        data-slot="freshness-chart"
        className={cn(COLORS, "flex w-full flex-col", className)}
        {...props}
      >
        <style>{CSS}</style>
        <p className="sr-only">
          {`${title}: ${live}% of ${files} files are current with live updates. A snapshot from ${format.date(model.start)} has ${Math.round(model.share)}% of them right, after ${model.all.length} changes across ${format.list(sources.map((source) => source.name))}.`}
        </p>
        <Header
          active={active}
          format={format}
          live={live}
          locale={locale}
          model={model}
          play={play}
          title={title}
        />

        {/* The plot, on a three-column grid: labels, the timeline, and (from
            sm up) the gutter. Only the middle column is measured. */}
        <div className="mx-5 mt-5 mb-4 grid grid-cols-[auto_minmax(0,1fr)] gap-x-3 sm:grid-cols-[auto_minmax(0,1fr)_5.25rem]">
          <Labels active={active} sources={sources} />
          <div
            ref={plotRef}
            className="relative min-w-0"
            style={{ height: geo.height }}
          >
            {measured && (
              <>
                <Timeline
                  active={active}
                  beat={beat}
                  format={format}
                  geo={geo}
                  live={live}
                  model={model}
                  progress={progress}
                  settled={settled}
                  sources={sources}
                />
                <Scrubber
                  active={active}
                  enabled={drawn}
                  format={format}
                  geo={geo}
                  model={model}
                  onAttend={() => setBeat((count) => count + 1)}
                  onPick={setPointed}
                />
              </>
            )}
            <AnimatePresence>
              {active && measured && (
                <motion.div
                  key="tip"
                  animate={{ opacity: 1, scale: 1, x: tip.x }}
                  className="pointer-events-none absolute top-0 left-0 z-10 origin-top-left"
                  exit={{
                    opacity: 0,
                    scale: 0.97,
                    transition: { duration: MOTION.tipOut },
                  }}
                  initial={{ opacity: 0, scale: 0.97, x: tip.x }}
                  transition={{
                    opacity: { duration: MOTION.tipIn, ease: EASE_OUT },
                    scale: { duration: MOTION.tipIn, ease: EASE_OUT },
                    x: GLIDE,
                  }}
                >
                  <ChangeCard
                    change={active}
                    format={format}
                    width={tip.width}
                  />
                </motion.div>
              )}
            </AnimatePresence>
          </div>
          <Gutter
            active={active}
            geo={geo}
            live={live}
            model={model}
            quiet={quiet}
            settled={settled}
            sources={sources}
          />
        </div>
      </div>
    </MotionConfig>
  );
};

"use client";

import {
  ArrowRight01Icon,
  Folder01Icon,
  NotionIcon,
  SlackIcon,
  StripeIcon,
} from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import type { IconSvgElement } from "@hugeicons/react";
import { useReducedMotion } from "motion/react";
import { useEffect, useState } from "react";
import type { ComponentProps } from "react";

import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";

/* ─────────────────────────────────────────────────────────────────────────
 * Source chat. One question and its answer in two lines: what happened,
 * then who changed which file. Under them, the sources the answer read.
 *
 * ANIMATION STORYBOARD
 *
 * Read top to bottom. Each value is ms after `play` turns true.
 *
 *  before   the question is already asked, waiting; the window is at its
 *           full height
 *  400ms   "Reading 4 sources" shimmers where the answer will be
 * 1500ms   the answer replaces it
 * 2100ms   the second line rises in under it
 * 2600ms   the sources rise in (staggered 100ms)
 *
 * A piece arrives the same way each time: it fades in, rises 12px and
 * comes into focus from a 4px blur, over 300ms. Every piece keeps its
 * place from the start, so the window never changes size. With reduced
 * motion the whole conversation fades in at once, and nothing moves.
 * ───────────────────────────────────────────────────────────────────────── */

const TIMING = {
  /** The answer replaces the shimmer. */
  answer: 1500,
  /** The answer's second line rises in. */
  note: 2100,
  /** The sources start staggering in. */
  sources: 2600,
  /** The shimmer starts. */
  thinking: 400,
};

/** The stages, in order: each one adds to the last. */
const STAGE = {
  answer: 3,
  note: 4,
  question: 1,
  sources: 5,
  thinking: 2,
} as const;

/** The sources' stagger, in ms. */
const STAGGER = 100;

/**
 * The chat's text: the question, the answer and its second line. No lone
 * word on a last line, and a word too long for a line (a deep file path)
 * breaks instead of running out of the window.
 */
const TEXT = "text-sm font-normal text-pretty wrap-break-word";

/**
 * The answer's line height, 22px at 14px: it runs to five lines on a phone.
 * It goes after TEXT wherever the two meet, since a text size resets the
 * line height before it.
 */
const PROSE = "leading-[calc(22/14)]";

/**
 * A source chip, 24px tall: 3px of padding round an 18px icon tile, and a
 * little more on the text side so the two edges look even. The tile's
 * corner is the chip's corner less that padding, so the curves run parallel.
 */
const CHIP =
  "bg-muted text-foreground justify-start gap-1.5 rounded-[0.4375rem] border-0 px-0 py-[0.1875rem] pr-2 pl-[0.1875rem] text-[0.8125rem] leading-[calc(18/13)] font-normal w-auto sm:w-fit forced-colors:border";
const TILE = "bg-card grid size-4.5 place-items-center rounded-[0.25rem]";

/**
 * How a piece arrives: a fade, a 12px rise and a 4px blur clearing. The
 * rise and the blur are only for people who take motion; the fade stays.
 */
const RISE = "transition-[opacity,translate,filter] duration-300 ease-out";
const HIDDEN = "opacity-0 motion-safe:translate-y-3 motion-safe:blur-xs";

const CSS = `
@keyframes ctx-shimmer { from { background-position: 100% 0 } to { background-position: -100% 0 } }
.ctx-shimmer { background: linear-gradient(90deg, var(--muted-foreground) 40%, var(--foreground) 50%, var(--muted-foreground) 60%) 0 0 / 200% 100%; -webkit-background-clip: text; background-clip: text; color: transparent; animation: ctx-shimmer 1.8s linear infinite; }
@media (prefers-reduced-motion: reduce) { .ctx-shimmer { animation: none; color: var(--muted-foreground); background: none; } }
`;

/** Something the answer read. */
export interface ChatSource {
  /** The source's name, shown on its chip. */
  name: string;
  /** Its icon: any icon from the Hugeicons core-free-icons package. */
  icon: IconSvgElement;
}

export interface SourceChatProps extends Omit<
  ComponentProps<"div">,
  "children"
> {
  /** The breadcrumb: where the chat lives, then its name. */
  crumbs?: [string, string];
  /** What the visitor asked, in the bubble on the right. */
  question?: string;
  /** The assistant's answer. */
  answer?: string;
  /** The answer's second line: who changed which file. */
  note?: string;
  /** The file that line names. Where it appears in `note` it is set apart
   * in the accent colour. */
  file?: string;
  /** What the answer read, as a row of chips under it. */
  sources?: ChatSource[];
  /** Starts the conversation. Flip it to true when the chat is in view. */
  play?: boolean;
}

export const DEMO_SOURCES: ChatSource[] = [
  { icon: SlackIcon, name: "Slack" },
  { icon: NotionIcon, name: "Notion" },
  { icon: StripeIcon, name: "Stripe" },
  { icon: Folder01Icon, name: "Files" },
];

/** The assistant's mark: a four-point spark. */
const Spark = () => (
  <svg aria-hidden className="size-3.5" fill="currentColor" viewBox="0 0 16 16">
    <path d="M8 1c.5 3.6 2.4 5.5 6 6v2c-3.6.5-5.5 2.4-6 6H8c-.5-3.6-2.4-5.5-6-6V7c3.6-.5 5.5-2.4 6-6Z" />
  </svg>
);

/** Runs the storyboard: one stage number, set by timers read from TIMING. */
const useStage = (play: boolean) => {
  const reduce = useReducedMotion();
  // The question is there from the start: the window waits on it.
  const [stage, setStage] = useState<number>(STAGE.question);
  useEffect(() => {
    if (!play) {
      return;
    }
    if (reduce) {
      setStage(STAGE.sources);
      return;
    }
    const timers = [
      setTimeout(() => setStage(STAGE.thinking), TIMING.thinking),
      setTimeout(() => setStage(STAGE.answer), TIMING.answer),
      setTimeout(() => setStage(STAGE.note), TIMING.note),
      setTimeout(() => setStage(STAGE.sources), TIMING.sources),
    ];
    return () => {
      for (const timer of timers) {
        clearTimeout(timer);
      }
    };
  }, [play, reduce]);
  return stage;
};

/**
 * The accent for the file's name. The theme's primary; on a dark ground it
 * is mixed toward white, since a deep primary is too dim there for text.
 */
const MARK =
  "text-primary dark:text-[color-mix(in_oklab,var(--primary)_60%,white)]";

/** A line of text with one phrase in it (the first match) set apart. */
const Marked = ({ mark, text }: { mark: string; text: string }) => {
  const at = mark ? text.indexOf(mark) : -1;
  if (at === -1) {
    return text;
  }
  return (
    <>
      {text.slice(0, at)}
      <span className={MARK}>{mark}</span>
      {text.slice(at + mark.length)}
    </>
  );
};

/** The sources the answer read, as a row of chips. */
const Sources = ({
  sources,
  stage,
}: {
  sources: ChatSource[];
  stage: number;
}) => (
  // No visible label: the chips say what they are. The list keeps a name
  // for screen readers.
  // On a phone the row is too short for four chips and would leave one
  // alone on a second line, so there they sit in two columns.
  <ul
    aria-label="Sources"
    className="mt-4 grid w-fit grid-cols-[auto_auto] gap-1.5 sm:flex sm:w-auto sm:flex-wrap"
    // Safari drops the list role from a list with no markers.
    role="list"
  >
    {sources.map((source, i) => (
      <Badge
        key={source.name}
        asChild
        className={cn(CHIP, RISE, stage < STAGE.sources && HIDDEN)}
        variant="secondary"
      >
        <li
          style={{
            transitionDelay:
              stage === STAGE.sources ? `${i * STAGGER}ms` : undefined,
          }}
        >
          <span className={TILE}>
            <HugeiconsIcon
              absoluteStrokeWidth
              aria-hidden
              icon={source.icon}
              size={12}
              strokeWidth={1}
            />
          </span>
          {source.name}
        </li>
      </Badge>
    ))}
  </ul>
);

export const SourceChat = ({
  // The no-break spaces keep "30 days" and "9 June" whole on a narrow line.
  answer = "The refund window went from 14 to 30\u00A0days on 9\u00A0June, so older orders now qualify. Product returns are flat over the same months.",
  className,
  crumbs = ["Chat", "Refund review"],
  file = "/policies/refunds.md",
  note = "Support ops made that change in /policies/refunds.md.",
  play = true,
  question = "Why are refunds up since June?",
  sources = DEMO_SOURCES,
  ...props
}: SourceChatProps) => {
  const stage = useStage(play);
  return (
    <div
      data-slot="source-chat"
      className={cn("flex w-full flex-col", className)}
      {...props}
    >
      <style>{CSS}</style>
      {/* The same size, weight and offset as the chart's title, so the two
          windows' first lines sit level. */}
      <div className="flex items-center gap-1.5 px-5 pt-5.5 pb-1.5 text-base font-normal">
        <span>{crumbs[0]}</span>
        <HugeiconsIcon
          absoluteStrokeWidth
          aria-hidden
          className="text-muted-foreground rtl:-scale-x-100"
          icon={ArrowRight01Icon}
          size={16}
          strokeWidth={1.5}
        />
        <span className="min-w-0 truncate">{crumbs[1]}</span>
      </div>

      <div className="flex flex-1 flex-col gap-6 px-5 pt-7 pb-6">
        {/* The bubble is as wide as its text allows, so its wrapping is
            the plain kind: the first line runs full and the bubble hugs
            it. Evening the lines out would leave the bubble wider than
            anything in it. */}
        <p
          className={cn(
            "bg-muted self-end rounded-lg px-3.5 py-2.5 forced-colors:border sm:max-w-[85%]",
            TEXT,
            "text-wrap",
            RISE,
            stage < STAGE.question && HIDDEN
          )}
        >
          <span className="sr-only">Question: </span>
          {question}
        </p>

        {/* On a phone the mark sits above the answer, not beside it: the
            40px it would take is a sixth of the line. */}
        <div className="flex flex-col gap-3 sm:flex-row">
          <span
            className={cn(
              "bg-foreground text-background grid size-7 shrink-0 place-items-center rounded-lg",
              RISE,
              stage < STAGE.thinking && HIDDEN
            )}
          >
            <Spark />
          </span>
          {/* Capped near 70 characters a line: on a tablet the window is
              wide enough for 80. */}
          <div className="min-w-0 flex-1 sm:max-w-[29rem]">
            {/* The shimmer and the answer share one cell: the answer holds
                the height from the start, so nothing below it moves. */}
            <div className="grid">
              <p
                aria-hidden
                className={cn(
                  "ctx-shimmer col-start-1 row-start-1 w-fit text-sm font-normal transition-opacity duration-200 sm:pt-[0.1875rem]",
                  PROSE,
                  stage !== STAGE.thinking && "opacity-0"
                )}
              >
                Reading {sources.length} sources
              </p>
              <p
                className={cn(
                  "col-start-1 row-start-1 sm:pt-[0.1875rem]",
                  TEXT,
                  PROSE,
                  RISE,
                  stage < STAGE.answer && HIDDEN
                )}
              >
                <span className="sr-only">Answer: </span>
                {answer}
              </p>
            </div>
            <p
              className={cn(
                "mt-2.5",
                TEXT,
                PROSE,
                RISE,
                stage < STAGE.note && HIDDEN
              )}
            >
              <Marked mark={file} text={note} />
            </p>
            <Sources sources={sources} stage={stage} />
          </div>
        </div>
      </div>
    </div>
  );
};
